def build():
    rows=[]
    for n,line in enumerate(DATA.splitlines(),1):
        area,topic,command,output,prompt,correct,bad1,bad2,technical,risk,impact,control=line.split('|')
        b1,why1=bad1.split('~');b2,why2=bad2.split('~')
        choices=[{'id':'a','text':correct},{'id':'b','text':b1},{'id':'c','text':b2}];random.Random(551029+n).shuffle(choices)
        explanation=f'✅ Doğru yanıt\n{correct}\n\n🔧 Teknik gerekçe\n{technical}\n\n⚠️ Risk\n{risk}\n\n💼 İş etkisi\n{impact}\n\n🛡️ Önerilen kontrol\n{control}\n\n❌ Diğer yanıtların değerlendirmesi\n• {b1}: {why1}.\n• {b2}: {why2}.'
        rows.append(dict(external_id=f'network-auditor-v1-{n:03}',number=n,chapter=(n-1)//11+1,area=area,topic=topic,kind='image',prompt=prompt,context=f'NovaTek ağ denetiminde Selin (Denetim Yöneticin) ve Eren (Ağ Sorumlusu) ile kanıt NW-{n:03} üzerinde çalışıyorsun. Alan: {AREAS[area]}. Görseldeki yapılandırma, trafik yolu veya logu inceleyerek karar ver. Kurgusal eğitim ortamıdır; üretim ağına bağlanman gerekmez.',options=choices,answer=['a'],explanation=explanation,hint='Kaynak, hedef, yön, protokol/port ve zaman kapsamını ayır. İzin, fiili bağlantı ve uygulama sonucu aynı kanıt değildir.',difficulty='beginner' if n<=22 else 'intermediate' if n<=44 else 'advanced',goals=[topic,AREAS[area]],base_xp=10,published=True,premium=True,order=n,card_pages=[],image=f'network-auditor/screen_{n:03}.png',evidence={'command':command,'output':output.replace('\\n','\n')},technical=technical,risk=risk,impact=impact,control=control))
    assert len(rows)==55,len(rows)
    assert [r['area'] for r in rows]==[a for a in AREAS for _ in range(11)]
    p={'slug':'network-auditor-v1','title':'Ağ Denetimi','description':'55 özgün görselli ve uygulamalı ağ denetimi kararı • 5 bölüm\nFirewall, VPN, VLAN, segmentasyon ve ağ loglarını gerçekçi yapılandırma ve akış kanıtlarından öğren. Her yanıtta teknik gerekçe, risk, iş etkisi ve önerilen kontrol.','modules':MODULES,'areas':AREAS,'questions':rows}
    (ROOT/'package.json').write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n')
    print('55 cases / 5 x 11 chapters')
if __name__=='__main__':build()
